create extension if not exists vector with schema extensions;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,avatar_url text,preferences jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(name) between 1 and 200),description text,settings jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.project_members(project_id uuid not null references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in('owner','admin','editor','viewer')),created_at timestamptz not null default now(),primary key(project_id,user_id));
create table if not exists public.chats(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,title text,model text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),chat_id uuid not null references public.chats(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('system','user','assistant','tool')),content text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.files(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,name text not null,storage_path text not null unique,mime_type text,size_bytes bigint check(size_bytes is null or size_bytes>=0),checksum text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.file_chunks(id uuid primary key default gen_random_uuid(),file_id uuid not null references public.files(id) on delete cascade,chunk_index integer not null check(chunk_index>=0),content text not null,embedding extensions.vector(1536),metadata jsonb not null default '{}',created_at timestamptz not null default now(),unique(file_id,chunk_index));
create table if not exists public.memories(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,content text not null,memory_type text not null default 'semantic',source text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.memory_embeddings(id uuid primary key default gen_random_uuid(),memory_id uuid not null unique references public.memories(id) on delete cascade,embedding extensions.vector(1536) not null,model text,created_at timestamptz not null default now());
create table if not exists public.mcp_connections(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,name text not null,server_url text,transport text,secret_ref text,config jsonb not null default '{}',enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.tools(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id) on delete cascade,name text not null,description text,source text,schema jsonb not null default '{}',enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,name));
create table if not exists public.tool_permissions(tool_id uuid not null references public.tools(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permission text not null check(permission in('use','admin')),created_at timestamptz not null default now(),primary key(tool_id,user_id));
create table if not exists public.github_connections(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_login text,installation_id bigint,access_token_ref text,scopes text[] not null default '{}',metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,account_login));
create table if not exists public.cowork_sessions(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,status text not null default 'active' check(status in('active','paused','completed','cancelled')),metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.cowork_members(session_id uuid not null references public.cowork_sessions(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in('owner','member','observer')),created_at timestamptz not null default now(),primary key(session_id,user_id));
create table if not exists public.permission_grants(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,resource_type text not null,resource_id uuid,action text not null,effect text not null default 'allow' check(effect in('allow','deny')),expires_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,project_id uuid references public.projects(id) on delete set null,action text not null,resource_type text,resource_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists projects_owner_idx on public.projects(owner_id);
create index if not exists project_members_user_idx on public.project_members(user_id);
create index if not exists chats_project_idx on public.chats(project_id);
create index if not exists messages_chat_created_idx on public.messages(chat_id,created_at);
create index if not exists files_project_idx on public.files(project_id);
create index if not exists file_chunks_file_idx on public.file_chunks(file_id);
create index if not exists memories_user_project_idx on public.memories(user_id,project_id);
create index if not exists mcp_connections_user_idx on public.mcp_connections(user_id);
create index if not exists github_connections_user_idx on public.github_connections(user_id);
create index if not exists cowork_sessions_owner_idx on public.cowork_sessions(owner_id);
create index if not exists audit_logs_user_created_idx on public.audit_logs(user_id,created_at desc);
alter table public.profiles enable row level security;
alter table public.projects enable row level security;
alter table public.project_members enable row level security;
alter table public.chats enable row level security;
alter table public.messages enable row level security;
alter table public.files enable row level security;
alter table public.file_chunks enable row level security;
alter table public.memories enable row level security;
alter table public.memory_embeddings enable row level security;
alter table public.mcp_connections enable row level security;
alter table public.tools enable row level security;
alter table public.tool_permissions enable row level security;
alter table public.github_connections enable row level security;
alter table public.cowork_sessions enable row level security;
alter table public.cowork_members enable row level security;
alter table public.permission_grants enable row level security;
alter table public.audit_logs enable row level security;
create policy profiles_self on public.profiles for all to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
create policy projects_select on public.projects for select to authenticated using(owner_id=(select auth.uid()) or exists(select 1 from public.project_members pm where pm.project_id=id and pm.user_id=(select auth.uid())));
create policy projects_insert on public.projects for insert to authenticated with check(owner_id=(select auth.uid()));
create policy projects_update on public.projects for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy projects_delete on public.projects for delete to authenticated using(owner_id=(select auth.uid()));
create policy project_members_select on public.project_members for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.projects p where p.id=project_id and p.owner_id=(select auth.uid())));
create policy project_members_write on public.project_members for all to authenticated using(exists(select 1 from public.projects p where p.id=project_id and p.owner_id=(select auth.uid()))) with check(exists(select 1 from public.projects p where p.id=project_id and p.owner_id=(select auth.uid())));
create policy chats_access on public.chats for all to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.project_members pm where pm.project_id=project_id and pm.user_id=(select auth.uid()))) with check(user_id=(select auth.uid()));
create policy messages_access on public.messages for all to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.chats c where c.id=chat_id and(c.user_id=(select auth.uid()) or exists(select 1 from public.project_members pm where pm.project_id=c.project_id and pm.user_id=(select auth.uid()))))) with check(user_id=(select auth.uid()));
create policy files_access on public.files for all to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.project_members pm where pm.project_id=project_id and pm.user_id=(select auth.uid()))) with check(user_id=(select auth.uid()));
create policy file_chunks_access on public.file_chunks for all to authenticated using(exists(select 1 from public.files f where f.id=file_id and(f.user_id=(select auth.uid()) or exists(select 1 from public.project_members pm where pm.project_id=f.project_id and pm.user_id=(select auth.uid()))))) with check(exists(select 1 from public.files f where f.id=file_id and f.user_id=(select auth.uid())));
create policy memories_access on public.memories for all to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.project_members pm where pm.project_id=project_id and pm.user_id=(select auth.uid()))) with check(user_id=(select auth.uid()));
create policy memory_embeddings_access on public.memory_embeddings for all to authenticated using(exists(select 1 from public.memories m where m.id=memory_id and m.user_id=(select auth.uid()))) with check(exists(select 1 from public.memories m where m.id=memory_id and m.user_id=(select auth.uid())));
create policy mcp_connections_access on public.mcp_connections for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy tools_access on public.tools for all to authenticated using(owner_id=(select auth.uid()) or owner_id is null) with check(owner_id=(select auth.uid()) or owner_id is null);
create policy tool_permissions_access on public.tool_permissions for all to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.tools t where t.id=tool_id and t.owner_id=(select auth.uid()))) with check(user_id=(select auth.uid()) or exists(select 1 from public.tools t where t.id=tool_id and t.owner_id=(select auth.uid())));
create policy github_connections_access on public.github_connections for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy cowork_sessions_access on public.cowork_sessions for all to authenticated using(owner_id=(select auth.uid()) or exists(select 1 from public.cowork_members cm where cm.session_id=id and cm.user_id=(select auth.uid()))) with check(owner_id=(select auth.uid()));
create policy cowork_members_access on public.cowork_members for all to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.cowork_sessions cs where cs.id=session_id and cs.owner_id=(select auth.uid()))) with check(user_id=(select auth.uid()) or exists(select 1 from public.cowork_sessions cs where cs.id=session_id and cs.owner_id=(select auth.uid())));
create policy permission_grants_access on public.permission_grants for all to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.projects p where p.id=project_id and p.owner_id=(select auth.uid()))) with check(user_id=(select auth.uid()) or exists(select 1 from public.projects p where p.id=project_id and p.owner_id=(select auth.uid())));
create policy audit_logs_select on public.audit_logs for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.projects p where p.id=project_id and p.owner_id=(select auth.uid())));
grant usage on schema public to authenticated;
grant select,insert,update,delete on all tables in schema public to authenticated;